// 채권자변동정보 조회서 — 가짜 값으로 만든 pdf.js 글자 조각(items: {s,x,y,w,h}) 견본 여러 꼴.
// 실제 서류의 '모양'(칸 위치·줄바꿈·쪽 나눔)만 흉내 내고 이름·번호·금액·날짜는 모두 지어낸 값이다.
const H = 8;
const wOf = (s, h = H) => [...s].reduce((a, ch) => a + (/[가-힣]/.test(ch) ? h : h * 0.55), 0);
const at = (s, x, y, h = H) => ({ s, x, y, w: wOf(s, h), h });                       // 왼쪽 맞춤
const mid = (s, cx, y, h = H) => at(s, cx - wOf(s, h) / 2, y, h);                    // 가운데 맞춤
const right = (s, xr, y, h = H) => at(s, xr - wOf(s, h), y, h);                      // 오른쪽 맞춤(금액)
// 글자 한 자씩 조각(홈택스형 PDF)
const chars = (s, x, y, h = H) => { const out = []; let cx = x; for (const ch of s) { const w = wOf(ch, h); if (ch.trim()) out.push({ s: ch, x: cx, y, w, h }); cx += w; } return out; };

// ── 꼴 1: 신용정보원형 — 표 머리 여러 줄(묶음 머리 '변제예정금액'), 기록 하나가 세 줄(기관명 위 · 전화번호 아래),
//          '신용카드/채권' 줄바꿈, 표가 여러 쪽에 걸침(쪽마다 머리 반복), 지급보증 기록, 미해제 연체 1건
function kcisHead(y0) {
  return [
    mid('채권자변동정보 조회서', 426, 528, 23), at('발급일시 : 2025-01-02 09:00', 59, 499), at('페이지 : 1/3', 742, 493),
    at('※ 업무목적 외 사용금지 및 관계자 외 누설금지', 626, 447),
    at('주민등록번호', 90, 422), at('800101-*******', 226, 422), at('성명', 366, 422), at('홍길동', 473, 422), at('조회일자', 581, 422), at("'25.01.02. 09:00", 701, 422)
  ];
}
function kcisLoanHeader(y) {
  return [mid('순번', 76, y), mid('구분', 160, y), mid('대출종류', 322, y), mid('기관명', 508, y), mid('발생일자', 645, y), mid('금액', 750, y)];
}
function kcisLoanRow(y, seq, cat, type, inst, date, amt) {
  return [mid(seq, 76, y), mid(cat, 160, y), mid(type, 322, y), mid(inst, 508, y), mid(date, 645, y), right(amt, 762, y)];
}
function kcisDelHeader(y) {
  return [
    mid('변제예정금액', 312, y + 16), mid('기한이익', 404, y + 16), mid('채권추심', 465, y + 16),
    mid('금융기관명', 117, y + 10), mid('채권구', 174, y + 10), mid('등록사유', 224, y + 10), mid('채무조정', 526, y + 10), mid('양도사유', 587, y + 10), mid('양수기관', 648, y + 10), mid('해제사유', 710, y + 10), mid('소멸시효', 771, y + 10),
    mid('순번', 68, y + 5), mid('상실여부', 404, y + 5), mid('위탁여부', 465, y + 5),
    mid('(전화번호)', 117, y), mid('분', 174, y), mid('발생일자', 224, y), mid('유형', 526, y), mid('(양도일자)', 587, y), mid('(양도금액)', 648, y), mid('(해제일자)', 710, y), mid('완성여부', 771, y),
    mid('원금', 282, y - 3), mid('이자', 343, y - 3), mid('(상실일자)', 404, y - 3), mid('(위탁업체)', 465, y - 3)
  ];
}
// 기록: 가운데 줄(순번·날짜·숫자) + 위 줄(기관명·채권구분 앞부분·해제사유) + 아래 줄(전화·채권구분 뒷부분·해제일자)
function kcisDelRow(y, o) {
  const it = [mid(o.seq, 68, y), mid(o.date, 224, y), right(o.p, 309, y), right(o.i, 370, y)];
  it.push(mid(o.inst, 117, y + 5), mid(o.phone, 117, y - 5));
  if (o.type2) it.push(mid(o.type, 174, y + 5), mid(o.type2, 174, y - 5)); else it.push(mid(o.type, 174, y));
  if (o.accel) it.push(mid(o.accel, 404, y + 5), mid(o.accelAt, 404, y - 5)); else it.push(mid('-', 404, y));
  if (o.collect2) it.push(mid(o.collect, 465, y + 5), mid(o.collect2, 465, y - 5)); else it.push(mid(o.collect, 465, y));
  it.push(mid('-', 526, y), mid('미양도', 587, y), mid('-', 648, y), mid('-', 771, y));
  if (o.release) it.push(mid(o.release, 710, y + 5), mid(o.releaseAt, 710, y - 5)); else it.push(mid('-', 710, y));
  return it;
}
function layoutKcis() {
  const p1 = [...kcisHead(), at('□ 채권자변동정보 안내', 59, 386, 11),
    at('1. 채권자변동정보는 연체 등 채권의 양수가 발생한 경우 금융기관이 등록하는 정보입니다.', 59, 330),
    at('(단위: 천원)', 765, 160), at('1. 채무현황', 52, 154, 17), ...kcisLoanHeader(133),
    ...kcisLoanRow(115, '1', '개인대출정보', '신용대출(0100)', '가나은행[본점]', '2021.04.05.', '30,000')];
  const p2 = [...kcisHead(), at('(단위: 천원)', 759, 396), ...kcisLoanHeader(388),
    ...kcisLoanRow(370, '2', '개인사업자대출', '운전자금(일반)(1031)', '다라은행[시험지점]', '2022.06.07.', '50,000'),
    ...kcisLoanRow(356, '3', '개인사업자대출', '지급보증(1501)', '가상신용보증재단[본점]', '2022.06.07.', '45,000'),
    ...kcisLoanRow(342, '4', '개인사업자대출', '이행지보(1801)', '가상보증보험[본사]', '2023.01.10.', '2,000'),
    ...kcisLoanRow(328, '5', '개인사업자대출', '신용대출(종합통장대출)(1061)', '마바（세종）[본점]', '2023.08.09.', '100,000')];
  const p3 = [...kcisHead(), at('(단위: 천원)', 765, 381), at('2. 연체채권의 채권자 변동 현황', 52, 375, 17), ...kcisDelHeader(342),
    ...kcisDelRow(316, { seq: '1', inst: '사아카드', phone: '(1500-0000 )', type: '신용카드', type2: '채권', date: "'20.03.04.", p: '1,200', i: '30', collect: '미위탁', release: '채무자 변제', releaseAt: "('20.05.06.)" }),
    ...kcisDelRow(292, { seq: '2', inst: '자차캐피탈', phone: '(02-000-0000 )', type: '일반대출', date: "'21.07.08.", p: '5,000', i: '120', accel: '상실', accelAt: "('21.09.01.)", collect: '위탁', collect2: '(가상신용정보)' }),
    at('종합신용정보집중기관 가상신용정보원', 225, 281, 15)];
  return [p1, p2, p3];
}

// ── 꼴 2: 다른 발급처 — 한 줄 기록, 칸 순서 바뀜(기관이 앞), 순번 대신 '번호', 구분 칸 없음, 금액 칸이 '대출잔액(원)'(원 단위·잔액),
//          날짜 2024-01-31 꼴, 연체 표는 '연체금액'·'해제일자'·'해제사유'가 따로 칸, 미해제 1건
