// ── 꼴 3: 글자 한 자씩 조각 + 머리 두 줄('대출/종류' · '발생/일자') + 단위 표시 없음(원 단위 금액) + 순번 칸 없음
function layoutChars() {
  const y = 600, p = [];
  p.push(...chars('채권자변동정보조회서', 200, 760, 16), ...chars('조회일자', 40, 730), ...chars("'24.12.31.", 100, 730));
  p.push(...chars('구분', 50, y + 6), ...chars('대출', 150, y + 6), ...chars('기관명', 260, y + 6), ...chars('발생', 380, y + 6), ...chars('금액', 480, y + 6));
  p.push(...chars('종류', 150, y - 2), ...chars('일자', 380, y - 2));
  p.push(...chars('개인대출정보', 30, y - 24), ...chars('주택담보대출(0230)', 120, y - 24), ...chars('하나둘은행[가상지점]', 240, y - 24), ...chars('2019.10.11.', 370, y - 24), ...chars('120,000,000', 460, y - 24));
  p.push(...chars('개인대출정보', 30, y - 40), ...chars('카드론(0041)', 130, y - 40), ...chars('셋넷카드[본사]', 250, y - 40), ...chars('2024.02.29.', 370, y - 40), ...chars('3,000,000', 468, y - 40));
  return [p];
}

module.exports = { layoutKcis, layoutOther, layoutChars };
